import {normalize} from './engine.mjs';
const $=id=>document.getElementById(id),node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
const label=(id,text)=>{($(id).querySelector('.label')||$(id)).textContent=text;};
export function setupReaderControls(api){
 let bookmarks=load('lectio.bookmarks',[]),words=load('lectio.words',[]),favorites=load('lectio.favorites',[]),selectedWord='',selectedContext=null,selectedMeaning=null;
 if(!Array.isArray(bookmarks))bookmarks=[];if(!Array.isArray(words))words=[];if(!Array.isArray(favorites))favorites=[];
 const store=(key,value)=>{try{localStorage.setItem('lectio.'+key,JSON.stringify(value));return true;}catch{api.toast('Could not save your change. Browser storage may be full.');return false;}};
 const point=()=>{const s=api.state();return s.book?{bookId:s.book.id,title:s.book.title,author:s.book.author,page:s.page,anchor:Math.max(0,api.anchor()),created:Date.now()}:null;};
 const hasBookmark=p=>p&&bookmarks.some(b=>b.bookId===p.bookId&&b.page===p.page&&b.anchor===p.anchor);
 function update(){const s=api.state(),p=point();$('bookmarkButton').setAttribute('aria-pressed',String(!!hasBookmark(p)));label('bookmarkButton',hasBookmark(p)?'Bookmarked':'Bookmark');label('favoriteButton',favorites.includes(s.book?.id)?'Favorited':'Favorite');$('favoriteButton').setAttribute('aria-pressed',String(favorites.includes(s.book?.id)));$('jumpPage').max=s.data?.pages.length||1;$('jumpPage').value=s.page+1;}
 function prefs(){const p=api.state().prefs;document.documentElement.style.setProperty('--reader-width',({narrow:620,comfortable:780,wide:980})[p.width]+'px');document.documentElement.style.setProperty('--paragraph-gap',p.paragraphGap||'1.2em');document.documentElement.dataset.lookup=String(p.lookup!==false);document.querySelectorAll('#passage .word').forEach((w,i)=>{w.tabIndex=p.lookup!==false&&i===0?0:-1;if(p.lookup===false)w.removeAttribute('role');else w.setAttribute('role','button');});$('readingWidth').value=p.width||'comfortable';$('paragraphGap').value=p.paragraphGap||'1.2em';$('tapLookup').checked=p.lookup!==false;}
 function saveFile(name,type,text){const u=URL.createObjectURL(new Blob([text],{type})),a=node('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);}
 function bookmark(){const p=point();if(!p)return;const i=bookmarks.findIndex(b=>b.bookId===p.bookId&&b.page===p.page&&b.anchor===p.anchor);const next=[...bookmarks];if(i>=0)next.splice(i,1);else next.unshift({...p,id:crypto.randomUUID(),excerpt:api.state().data.pages[p.page][p.anchor]?.slice(0,180)||'',note:''});if(store('bookmarks',next)){bookmarks=next;api.toast(i>=0?'Bookmark removed.':'Reading place bookmarked.');update();}}
 $('bookmarkButton').onclick=bookmark;$('favoriteButton').onclick=()=>{const id=api.state().book?.id;if(!id)return;const next=favorites.includes(id)?favorites.filter(x=>x!==id):[id,...favorites];if(store('favorites',next)){favorites=next;update();}};
 function meaningLine(m){const d=node('p',undefined,'saved-meaning');d.append(node('strong',m.head),' ',node('span',m.pos||'','whitaker-pos'),node('br'),m.senses);return d;}
 function sentenceWith(sentence,word){const d=node('p',undefined,'saved-excerpt'),key=normalize(word),parts=sentence.split(/([\p{L}\p{M}]+)/u);let marked=false;for(const part of parts){if(!marked&&normalize(part)===key){d.append(node('mark',part));marked=true;}else d.append(part);}return d;}
 // Flashcards: Latin word in its sentence; reveal Whitaker's meaning; "Again" returns it to this session, "Got it" spaces it out (1, 3, 7, 16, 35 days).
 function review(queue){const list=$('savedList'),DAYS=[0,1,3,7,16,35];let seen=0,known=0;queue=queue.sort((a,b)=>(a.due||0)-(b.due||0));
  const card=async()=>{list.replaceChildren();if(!queue.length){$('savedCount').textContent='Review finished';list.append(node('p',`${seen} card${seen===1?'':'s'} reviewed, ${known} known.`,'review-done'));const back=node('button','Back to saved words');back.onclick=renderSaved;list.append(back);return;}
   const w=queue[0];$('savedCount').textContent=`${queue.length} left in this review`;const box=node('section',undefined,'flashcard');box.append(node('p',w.word,'flash-word'));if(w.sentence)box.append(sentenceWith(w.sentence,w.word));box.append(node('p',[w.author,w.title].filter(Boolean).join(' · '),'muted'));
   const reveal=node('button','Show meaning','primary');box.append(reveal);list.append(box);reveal.focus();
   reveal.onclick=async()=>{let m=w.meaning;if(!m){try{const r=(await api.whitaker(w.word))[0];if(r){m={head:r.head,pos:r.pos,senses:r.senses};const next=words.map(x=>x.id===w.id?{...x,meaning:m}:x);if(store('words',next))words=next;}}catch{}}
    reveal.replaceWith(m?meaningLine(m):node('p','No short definition found; open the word to see Lewis & Short.','muted'));
    const row=node('div',undefined,'review-actions'),again=node('button','Again'),got=node('button','Got it','primary'),look=node('button','Open dictionary','quiet');
    const grade=ok=>{seen++;if(ok)known++;const cur=words.find(x=>x.id===w.id)||w,boxN=ok?Math.min((cur.box||0)+1,DAYS.length-1):0,next=words.map(x=>x.id===w.id?{...x,box:boxN,due:Date.now()+(ok?DAYS[boxN]*864e5:0)}:x);if(store('words',next))words=next;queue.shift();if(!ok)queue.push(w);card();};
    again.onclick=()=>grade(false);got.onclick=()=>grade(true);look.onclick=()=>{$('savedDialog').close();api.lookup(w.word,w.sentence?{sentence:w.sentence,paragraph:w.anchor}:null);};row.append(again,got);box.append(row,look);got.focus();};
  };card();}
 function renderSaved(){const kind=$('savedKind').value,list=$('savedList');list.replaceChildren();const records=kind==='words'?words:bookmarks;$('savedCount').textContent=`${records.length} saved ${kind==='words'?'word':'place'}${records.length===1?'':'s'}`;
  if(kind==='words'&&records.length){const due=words.filter(w=>(w.due||0)<=Date.now()).length,go=node('button',due?`Review ${due} word${due===1?'':'s'} due`:'Review all words','primary review-start');go.onclick=()=>review(due?words.filter(w=>(w.due||0)<=Date.now()):[...words]);list.append(go);}if(!records.length){list.append(node('p',kind==='words'?'Save a word from its dictionary panel to revisit it here.':'Bookmark a paragraph while reading to keep it here.','muted'));return;}
  for(const record of records){const card=node('section',undefined,'saved-card'),open=node('button',kind==='words'?record.word:record.title,'saved-open');open.onclick=async()=>{$('savedDialog').close();try{if(kind==='words')api.lookup(record.word);else await api.navigate(record.bookId,record.page,record.anchor);}catch(e){api.toast(e.message);}};card.append(open,node('p',`${record.author||''} · ${record.title||''} · passage ${record.page+1}`,'muted'));if(kind==='words'){if(record.meaning)card.append(meaningLine(record.meaning));if(record.sentence)card.append(sentenceWith(record.sentence,record.word));else if(record.excerpt)card.append(node('p',record.excerpt,'saved-excerpt'));}else if(record.excerpt)card.append(node('p',record.excerpt,'saved-excerpt'));
   if(kind==='bookmarks'){const note=node('textarea');note.rows=2;note.placeholder='Add a note to this bookmark…';note.value=record.note||'';note.setAttribute('aria-label','Note for '+record.title);note.onchange=()=>{const next=bookmarks.map(b=>b.id===record.id?{...b,note:note.value}:b);if(store('bookmarks',next))bookmarks=next;};card.append(note);}
   const remove=node('button','Remove','quiet');remove.onclick=()=>{const next=records.filter(x=>x.id!==record.id);if(store(kind==='words'?'words':'bookmarks',next)){if(kind==='words')words=next;else bookmarks=next;renderSaved();update();}};card.append(remove);list.append(card);
  }
 }
 $('savedButton').onclick=()=>{renderSaved();api.show('savedDialog');};$('savedKind').onchange=renderSaved;
 $('saveWordButton').onclick=()=>{if(!selectedWord)return;const key=normalize(selectedWord);if(words.some(w=>normalize(w.word)===key)){api.toast('This word is already saved.');return;}const p=point()||{},anchor=selectedContext?.paragraph??p.anchor,next=[{...p,anchor,id:crypto.randomUUID(),word:selectedWord,sentence:selectedContext?.sentence||'',meaning:selectedMeaning,excerpt:api.state().data?.pages[p.page]?.[anchor]?.slice(0,180)||''},...words];if(store('words',next)){words=next;$('saveWordButton').textContent='✓ Word saved';api.toast('Word saved for later.');}};
 document.addEventListener('lectio:meaning',e=>{if(e.detail.word!==selectedWord)return;selectedMeaning=e.detail.meaning;const i=words.findIndex(w=>normalize(w.word)===normalize(selectedWord));if(i>=0&&!words[i].meaning&&selectedMeaning){const next=words.map((w,j)=>j===i?{...w,meaning:selectedMeaning}:w);if(store('words',next))words=next;}});
 document.addEventListener('lectio:lookup',e=>{selectedWord=e.detail.word;selectedContext=e.detail.context;selectedMeaning=null;$('saveWordButton').disabled=!selectedWord;$('saveWordButton').textContent=words.some(w=>normalize(w.word)===normalize(selectedWord))?'✓ Word saved':'＋ Save word';});
 $('dictionaryButton').onclick=()=>{api.lookup('');setTimeout(()=>$('lookupInput').focus(),0);};
 let searchTimer;
 function find(){const {book,data}=api.state(),q=normalize($('textSearch').value.trim());$('searchResults').replaceChildren();if(!book||!data||q.length<2){$('searchStatus').textContent='Enter at least two letters. Searches the whole current text; macrons and u/v variants are ignored.';return;}
  const hits=[];data.pages.forEach((paragraphs,page)=>paragraphs.forEach((text,anchor)=>{if(normalize(text).includes(q))hits.push({page,anchor,text});}));$('searchStatus').textContent=`${hits.length} matching paragraphs in ${book.title}${hits.length>200?' · showing the first 200':''}`;
  for(const h of hits.slice(0,200)){const b=node('button',undefined,'search-result');const index=normalize(h.text).indexOf(q),start=Math.max(0,index-55);b.append(node('strong','Passage '+(h.page+1)),node('span',(start?'…':'')+h.text.slice(start,start+220).replace(/\s+/g,' ')+'…'));b.onclick=async()=>{$('searchDialog').close();await api.navigate(book.id,h.page,h.anchor);requestAnimationFrame(()=>{const p=$('passage').children[h.anchor];p?.classList.add('search-match');p?.scrollIntoView({block:'center'});});};$('searchResults').append(b);}
 }
 function openFind(){if(!api.state().book)return;api.show('searchDialog');$('searchBook').textContent=api.state().book.title;$('textSearch').focus();find();}
 $('findButton').onclick=openFind;$('textSearch').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(find,180);};$('textSearchForm').onsubmit=e=>{e.preventDefault();clearTimeout(searchTimer);find();};
 $('jumpForm').onsubmit=e=>{e.preventDefault();const n=Number($('jumpPage').value),s=api.state();if(!Number.isInteger(n)||n<1||n>s.data.pages.length){api.toast('Choose a passage between 1 and '+s.data.pages.length+'.');return;}$('tocDialog').close();api.navigate(s.book.id,n-1,0).catch(e=>api.toast(e.message));};
 for(const [id,key] of [['readingWidth','width'],['paragraphGap','paragraphGap'],['tapLookup','lookup']])$(id).onchange=()=>{api.state().prefs[key]=$(id).type==='checkbox'?$(id).checked:$(id).value;api.applyPrefs();prefs();};
 function focus(value){document.body.classList.toggle('focus-reading',value);label('focusButton',value?'Exit focus':'Focus');$('focusButton').setAttribute('aria-pressed',String(value));$('exitFocus').hidden=!value;}
 $('focusButton').onclick=()=>focus(!document.body.classList.contains('focus-reading'));$('exitFocus').onclick=()=>focus(false);
 $('exportText').onclick=()=>{const s=api.state();if(!s.book)return;saveFile(s.book.title.replace(/[^\p{L}\p{N} -]/gu,'').slice(0,90)+'.txt','text/plain;charset=utf-8',`${s.book.author}\n${s.book.title}\n${s.book.source||'Personal text'}\n\n`+s.data.pages.flat().join('\n\n'));};
 $('exportBackup').onclick=async()=>{try{const s=api.state();saveFile('Lectio-reading-backup-'+new Date().toISOString().slice(0,10)+'.json','application/json',JSON.stringify({format:'lectio-reading-backup',version:1,exportedAt:new Date().toISOString(),preferences:s.prefs,positions:s.positions,favorites,bookmarks,words,personalTexts:await api.personalTexts()},null,2));}catch(e){api.toast('Backup could not be created: '+e.message);}};
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){const dialogs=[...document.querySelectorAll('dialog[open]')];if(dialogs.length){e.preventDefault();dialogs.at(-1).close();}else if(document.body.classList.contains('focus-reading'))focus(false);return;}if(e.target.closest('input,textarea,select,[contenteditable]'))return;
  // The desktop definition panel is non-modal: keep reading shortcuts available beside it.
  const modal=[...document.querySelectorAll('dialog[open]')].some(d=>{try{return d.matches(':modal');}catch{return d.id!=='wordDialog';}});if(modal)return;
  if(e.metaKey||e.ctrlKey)return;
  const click=id=>{e.preventDefault();$(id).click();};
  if(['ArrowLeft','ArrowRight'].includes(e.key)&&(e.altKey||!e.target.closest('.word'))){click(e.key==='ArrowLeft'?'barPrevious':'barNext');return;}
  if(e.altKey)return;
  const key=e.key.length===1?e.key.toLowerCase():e.key;
  if(key==='?'||(key==='/'&&e.shiftKey))click('shortcutsButton');
  else if(key==='/'||key==='f'){e.preventDefault();openFind();}
  else if(key==='b'){e.preventDefault();bookmark();}
  else{const target={l:'libraryButton',t:'tocButton',d:'dictionaryButton',k:'savedButton',n:'themeButton',s:'settingsButton',z:'focusButton'}[key];if(target)click(target);}
 });
 document.addEventListener('lectio:page',()=>{update();prefs();});window.addEventListener('scroll',()=>{clearTimeout(update.timer);update.timer=setTimeout(update,250);},{passive:true});
 return {isFavorite:id=>favorites.includes(id),refresh:update,preferences:prefs};
}
